create table public.analytics_snapshots (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, snapshot_date date not null, metrics jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique(project_id, snapshot_date));
create table public.exports (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, type text not null, format text not null, status text not null default 'queued' check (status in ('queued', 'running', 'completed', 'failed')), file_path text, storage_path text, metadata jsonb not null default '{}'::jsonb, requested_by uuid not null references auth.users(id), created_at timestamptz not null default now(), completed_at timestamptz);
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, workspace_id uuid not null references public.workspaces(id) on delete cascade, project_id uuid references public.projects(id) on delete cascade, type text not null, title text not null, message text not null, severity text not null default 'info' check (severity in ('info', 'success', 'warning', 'error')), read boolean not null default false, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.audit_events (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, project_id uuid references public.projects(id) on delete cascade, user_id uuid not null references auth.users(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.user_settings (user_id uuid primary key references auth.users(id) on delete cascade, theme text not null default 'system', default_workspace uuid references public.workspaces(id) on delete set null, notifications jsonb not null default '{}'::jsonb, ai_preferences jsonb not null default '{}'::jsonb, editor_preferences jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table public.workspace_settings (workspace_id uuid primary key references public.workspaces(id) on delete cascade, visibility text not null default 'private' check (visibility in ('private', 'workspace')), default_architecture_settings jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create index analytics_project_date_idx on public.analytics_snapshots(project_id, snapshot_date desc); create index exports_project_idx on public.exports(project_id, created_at desc); create index notifications_user_idx on public.notifications(user_id, read, created_at desc); create index audit_project_idx on public.audit_events(project_id, created_at desc);
alter table public.analytics_snapshots enable row level security; alter table public.exports enable row level security; alter table public.notifications enable row level security; alter table public.audit_events enable row level security; alter table public.user_settings enable row level security; alter table public.workspace_settings enable row level security;
create policy analytics_access on public.analytics_snapshots for select using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))); create policy analytics_manage on public.analytics_snapshots for all using (public.is_workspace_member((select workspace_id from public.projects where id = project_id)));
create policy exports_access on public.exports for select using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))); create policy exports_insert on public.exports for insert with check (requested_by = auth.uid() and public.is_workspace_member((select workspace_id from public.projects where id = project_id)));
create policy notifications_self on public.notifications for select using (user_id = auth.uid()); create policy notifications_update on public.notifications for update using (user_id = auth.uid());
create policy audit_access on public.audit_events for select using (public.is_workspace_member(workspace_id)); create policy audit_insert on public.audit_events for insert with check (user_id = auth.uid() and public.is_workspace_member(workspace_id));
create policy settings_self on public.user_settings for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy workspace_settings_access on public.workspace_settings for select using (public.is_workspace_member(workspace_id)); create policy workspace_settings_manage on public.workspace_settings for all using (public.is_workspace_admin(workspace_id)) with check (public.is_workspace_admin(workspace_id));
alter publication supabase_realtime add table public.notifications, public.exports, public.analytics_snapshots;
insert into storage.buckets (id, name, public) values ('project-exports', 'project-exports', false), ('project-assets', 'project-assets', false), ('avatars', 'avatars', false) on conflict (id) do nothing;
create policy storage_project_exports_read on storage.objects for select using (false);
create policy storage_project_exports_insert on storage.objects for insert with check (false);
create policy storage_project_assets_read on storage.objects for select using (false);
create policy storage_project_assets_insert on storage.objects for insert with check (false);
create policy storage_avatars_self on storage.objects for all using (bucket_id = 'avatars' and owner_id = auth.uid()::text) with check (bucket_id = 'avatars' and owner_id = auth.uid()::text);